       AMInv len n cap A s p regs' mem' mo' -> m_channel_reader mo' = m_channel_reader mo -> realizes asegs (mkCfg msF' mo') K) ->
    (len = Z.of_nat (length data) -> forall regs' mem' msF' mo',
