      eapply (aleft_next k (as_AL H s) (as_AL H s2) (as_AL H s3) (2 * cap) cap); [lia | exact HAL | lia | lia | exact HALC | exact HALG].
    - exact RHH.
    - eexists. exact CB2H.
    - exact AD2H.
    - fold bsrc. exact HD2H.
    - eapply mstatics_frameL; [exact STG | exact FMH].
    - rewrite EFS. exact Hfs.
    - rewrite EFDS. exact Hfd3.
    - rewrite EFDS. exact Hfd1.
    - rewrite EFDS. exact Hfd2.
    - exact RDH.
  Qed.

  (* [comment removed for export] *)
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma loop_sound : forall (n : nat) len cap A s p regs mem msF mo K,
    Z.of_nat (length data) - len <= Z.of_nat n ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 AREAD_STUB) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    ARInv len cap A s p regs mem mo ->
    (forall cap' A' s' p' regs' mem' msF' mo',
       as_VIS H s' msF' = mkst regs' (Z_to_bv 64 0x10e4e0) mem' rom -> as_AKREL H s' (mkCfg msF' mo') ->
       ACInv cap' A' s' p' regs' mem' mo' -> m_channel_reader mo' = m_channel_reader mo -> realizes asegs (mkCfg msF' mo') K) ->
    (MAX_INPUT <= Z.of_nat (length data) -> forall A' s' p' regs' mem' msF' mo',
       as_VIS H s' msF' = mkst regs' (Z_to_bv 64 0xa2f18) mem' rom -> as_AKREL H s' (mkCfg msF' mo') ->
       ARfInv A' s' p' regs' mem' mo' -> m_channel_reader mo' = m_channel_reader mo -> realizes asegs (mkCfg msF' mo') K) ->
    realizes asegs (mkCfg msF mo) K.
  Proof using HCEIL H HH DL sp0 pp tid can path data fs0 mem0 Hvsp HCE Hdata Htid TRC LIVE.
    (* Text proof on the shape of openssl/echconfiglist_parser's As/AsMainLoop.v [loop_sound]; each step's
       reader equation is chained to [mo] before the exits are handed on. *)
    induction n as [|n IH]; intros len cap A s p regs mem msF mo K Hn HV HA RI KEOF KREF.
    - (* [comment removed for export] *)
      pose proof (ari_len _ _ _ _ _ _ _ _ RI) as Hlen.
      eapply read_step; [exact HV | exact HA | exact RI | | intros _; exact (KEOF cap A s p)].
      intros regs' mem' msF' mo' n0 _ _ MI _. exfalso. pose proof (ami_len _ _ _ _ _ _ _ _ _ MI). lia.
    - pose proof (ari_len _ _ _ _ _ _ _ _ RI) as Hlen. pose proof (ari_cap _ _ _ _ _ _ _ _ RI) as Hcap.
      eapply read_step; [exact HV | exact HA | exact RI | | intros _; exact (KEOF cap A s p)].
      intros regs1 mem1 msF1 mo1 n0 HV1 HA1 MI CR1. pose proof (ami_len _ _ _ _ _ _ _ _ _ MI) as Hlen1.
      (* The two exits, re-based from a later step model [mo2] (whose reader is [mo]'s) to [mo]. *)
      assert (KEOF' : forall mo2, m_channel_reader mo2 = m_channel_reader mo ->
        forall cap' A' s' p' regs' mem' msF' mo',
          as_VIS H s' msF' = mkst regs' (Z_to_bv 64 0x10e4e0) mem' rom -> as_AKREL H s' (mkCfg msF' mo') ->
          ACInv cap' A' s' p' regs' mem' mo' -> m_channel_reader mo' = m_channel_reader mo2 -> realizes asegs (mkCfg msF' mo') K).
      { intros mo2 CR2 cap' A' s' p' regs' mem' msF' mo' HV' HA' CI' CR'.
        apply (KEOF cap' A' s' p' regs' mem' msF' mo' HV' HA' CI'). rewrite CR'. exact CR2. }
      assert (KREF' : forall mo2, m_channel_reader mo2 = m_channel_reader mo ->
        MAX_INPUT <= Z.of_nat (length data) -> forall A' s' p' regs' mem' msF' mo',
          as_VIS H s' msF' = mkst regs' (Z_to_bv 64 0xa2f18) mem' rom -> as_AKREL H s' (mkCfg msF' mo') ->
          ARfInv A' s' p' regs' mem' mo' -> m_channel_reader mo' = m_channel_reader mo2 -> realizes asegs (mkCfg msF' mo') K).
      { intros mo2 CR2 HM A' s' p' regs' mem' msF' mo' HV' HA' RF' CR'.
        apply (KREF HM A' s' p' regs' mem' msF' mo' HV' HA' RF'). rewrite CR'. exact CR2. }
      destruct (Z.eq_dec (len + n0) cap) as [Heq | Hne].
      + destruct (Z_lt_le_dec cap MAX_INPUT) as [Hsmall | Hbig].
        * eapply m_grow; [exact HV1 | exact HA1 | exact MI | exact Heq | exact Hsmall |]. intros regs2 mem2 msF2 mo2 A2 s2 p2 HV2 HA2 RI2 CR2.
          assert (CR21 : m_channel_reader mo2 = m_channel_reader mo) by (rewrite CR2; exact CR1).
          eapply (IH cap); [lia | exact HV2 | exact HA2 | exact RI2 | exact (KEOF' mo2 CR21) | exact (KREF' mo2 CR21)].
        * eapply m_refuse; [exact HV1 | exact HA1 | exact MI | exact Heq | exact Hbig |]. intros regs2 mem2 msF2 mo2 HV2 HA2 RF2 CR2.
          apply (KREF ltac:(lia) A s p regs2 mem2 msF2 mo2 HV2 HA2 RF2). rewrite CR2. exact CR1.
      + eapply m_cont; [exact HV1 | exact HA1 | exact MI | exact Hne |]. intros regs2 mem2 msF2 mo2 HV2 HA2 RI2 CR2.
        assert (CR21 : m_channel_reader mo2 = m_channel_reader mo) by (rewrite CR2; exact CR1).
        eapply (IH (len + n0)); [lia | exact HV2 | exact HA2 | exact RI2 | exact (KEOF' mo2 CR21) | exact (KREF' mo2 CR21)].
  Qed.
End Loop.
